const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),asset=require('./asset-version');
const root=path.resolve(__dirname,'..'),origin='https://outbound-lead-generation.com',route='/guides/cold-email-follow-up/',locales=['en','es','ca','fr'];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const json=v=>JSON.stringify(v).replace(/</g,'\\u003c');const plain=s=>String(s).replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&#39;|&apos;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>');
const legacy={'guide-section-1':'f-decision','guide-section-2':'f-timing','guide-section-3':'f-examples','guide-section-3-example-1':'f-thread','guide-section-3-example-2':'f-examples','guide-section-3-example-3':'f-examples','guide-section-4':'f-replies','guide-section-5':'f-handoff','guide-section-6':'f-measure','guide-section-7':'f-service','saved-campaign-reminder':'f-examples','buyer-worksheet':'f-review','buyer-decision-guide':'f-service','frequently-asked-questions':'f-faq',sources:'f-sources'};
function tool(p){const u=p.ui;const field=k=>'<label class="j-field'+(['previous','next'].includes(k)?' j-wide':'')+'">'+esc(u.fields[k])+(k==='state'||k==='evidence'?'<select data-followup-field="'+k+'">'+Object.entries(k==='state'?u.states:u.evidence).map(([key,value])=>'<option value="'+key+'">'+esc(value)+'</option>').join('')+'</select>':'<textarea data-followup-field="'+k+'" maxlength="12000" rows="3" autocomplete="off"></textarea>')+'</label>';const button=(a,t)=>'<button class="j-button cursor-interaction" type="button" data-'+a+' disabled>'+esc(t)+'</button>';
return '<details class="j-tool" data-workbook><summary class="cursor-interaction">'+esc(u.summary)+'</summary><div class="j-tool-inner"><p class="j-small" id="followup-privacy">'+esc(u.privacy)+'</p><p class="j-small">'+esc(u.fallback)+'</p><label class="j-field" data-draft-picker-label hidden>'+esc(u.picker)+'<select data-draft-picker></select></label><div class="j-review-form" aria-describedby="followup-privacy"><div class="j-fields">'+['context','previous','state','next'].map(field).join('')+'</div><details class="j-advanced"><summary class="cursor-interaction">'+esc(u.advanced)+'</summary><div class="j-fields">'+['unknown','stop','owner','evidence'].map(field).join('')+'</div></details><div class="j-row">'+button('build-review',u.build)+button('new-draft',u.add)+button('remove',u.remove)+button('clear',u.clear)+'</div></div><div data-clear-confirm class="j-confirm" hidden><p>'+esc(u.confirm)+'</p><div class="j-row">'+button('clear-yes',u.yes)+button('clear-no',u.no)+'</div></div><details class="j-advanced"><summary class="cursor-interaction">'+esc(u.example)+'</summary><label class="j-field">'+esc(u.example)+'<select data-example-select><option value="">'+esc(u.example)+'</option>'+p.samples.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')+'</select></label><div class="j-row">'+button('use-selected',u.load)+'</div></details><div class="j-report" data-report hidden><h3>'+esc(u.heading)+'</h3><p>'+esc(u.reviewNote)+'</p><div class="j-reply-decision"><h4>'+esc(u.result)+'</h4><p data-decision></p></div><dl data-report-notes></dl><div class="j-checks" data-review-checks><h4>'+esc(u.judgmentsTitle)+'</h4>'+u.checks.map(t=>'<label><input type="checkbox"><span>'+esc(t)+'</span></label>').join('')+'</div><div class="j-row">'+button('edit-review',u.edit)+button('print',u.print)+'</div></div><div class="j-row">'+button('export',u.export)+'</div><div data-csv-output hidden><label class="j-field">'+esc(u.csv)+'<textarea data-csv-text readonly rows="7"></textarea></label>'+button('close-csv',u.closeCsv)+'</div><p class="j-status" role="status" aria-live="polite" data-workbook-status></p></div></details>';}
for(const l of locales){const p=JSON.parse(fs.readFileSync(path.join(root,'data/follow-up-article-20261030/'+l+'.json'))),pre=l==='en'?'':'/'+l,url=origin+pre+route,file=path.join(root,(pre+route).slice(1),'index.html');let h=fs.readFileSync(file,'utf8'),main=p.html;const header=h.match(/<header class="site-header journal-site-header">[\s\S]*?<\/header>/)[0];main=main.replace('<p class="j-email-body">Hi [first name],\n\nJust checking in on this.\n\nBest regards,\n[sender]</p>','<p class="j-email-body" lang="en">Hi [first name],\n\nJust checking in on this.\n\nBest regards,\n[sender]</p>');main=main.replace('<div data-followup-tool></div>',tool(p));
const sections=[...main.matchAll(/<section class="[^"]*j-section[^"]*" id="([^"]+)" data-section-label="([^"]+)">/g)].map(m=>({id:m[1],label:m[2]}));assert.equal(sections.length,14);const links=sections.map(s=>'<a class="j-section-link cursor-interaction" data-jump="'+s.id+'" href="#'+s.id+'">'+esc(s.label)+'</a>').join('');main=main.replace(/<nav([^>]*data-contents[^>]*)><\/nav>/g,'<nav$1>'+links+'</nav>');for(const [id,target]of Object.entries(legacy)){
 const anchor='<span class="legacy-anchor" id="'+id+'" aria-hidden="true"></span>';
 if(id==='guide-section-3-example-2'||id==='guide-section-3-example-3'){
  let n=0;const wanted=id.endsWith('-2')?1:2;main=main.replace(/<div class="j-example">/g,m=>++n===wanted?anchor+m:m);
 }else if(id==='saved-campaign-reminder'){
  const section=main.indexOf('id="f-examples"'),h3s=[...main.slice(section).matchAll(/<h3>/g)];const at=section+h3s[2].index;main=main.slice(0,at)+anchor+main.slice(at);
 }else main=main.replace(new RegExp('(<section[^>]*id="'+target+'"[^>]*>)'),'$1'+anchor);
}
const faqs=[...main.matchAll(/<details><summary class="cursor-interaction">([\s\S]*?)<\/summary><p>([\s\S]*?)<\/p><\/details>/g)].map(m=>({question:plain(m[1]),answer:plain(m[2])}));assert.equal(faqs.length,7);const config={locale:l,ui:p.ui,samples:p.samples,legacy};h=h.replace(/<div id="beespoke-follow-up-full"><div class="j-page">(<main[\s\S]*?<\/main>)\s*<\/div><script type="application\/json" data-followup-config>[\s\S]*?<\/script><\/div>/,'$1');h=h.replace(/<main\b[^>]*>[\s\S]*?<\/main>/,'<div id="beespoke-follow-up-full"><div class="j-page">'+main+'</div><script type="application/json" data-followup-config>'+json(config)+'</script></div>');h=h.replace(/<body\b([^>]*)>/,(m,a)=>a.includes('follow-up-page')?m:'<body'+a.replace(/class="([^"]+)"/,'class="$1 follow-up-page"')+'>');h=h.replace(/<title>[\s\S]*?<\/title>/,'<title>'+esc(p.title)+'</title>');
for(const [type,name,value]of [['name','description',p.description],['property','og:title',p.title],['property','og:description',p.description],['name','twitter:title',p.title],['name','twitter:description',p.description]])h=h.replace(new RegExp('(<meta '+type+'="'+name+'" content=")[^"]*(")'),(m,a,z)=>a+esc(value)+z);
h=h.replace(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g,(m,raw)=>{const d=JSON.parse(raw);for(const n of d['@graph']||[d]){if(n['@type']==='Article'){n.name=p.h1;n.headline=p.h1;n.description=p.description;n.inLanguage=l;n.datePublished=p.datePublished;n.dateModified=p.dateModified;}if(n['@type']==='FAQPage')n.mainEntity=faqs.map(f=>({'@type':'Question',name:f.question,acceptedAnswer:{'@type':'Answer',text:f.answer}}));if(n['@type']==='BreadcrumbList')n.itemListElement.at(-1).name=p.h1;}return '<script type="application/ld+json">'+json(d)+'</script>';});
h=h.replace(/<link rel="stylesheet" href="\/(?:buyer-guide-worksheet|outbound-message-examples|follow-up-article)\.css[^\"]*">/g,'').replace(/<script src="\/(?:buyer-guide-worksheet|follow-up-article)\.js[^\"]*" defer><\/script>/g,'');h=h.replace('</head>','<link rel="stylesheet" href="'+asset('/follow-up-article.css')+'"><script src="'+asset('/follow-up-article.js')+'" defer></script></head>');assert.equal(h.match(/<header class="site-header journal-site-header">[\s\S]*?<\/header>/)[0],header);fs.writeFileSync(file,h);
const hub=path.join(root,(pre+'/resources/').slice(1),'index.html');let lib=fs.readFileSync(hub,'utf8');const re=new RegExp('(<a class="journal-resource-link" href="'+pre+route+'"[^>]*><div><h2[^>]*>)[\\s\\S]*?(</h2>)(?:<p>[\\s\\S]*?</p>)?');assert(re.test(lib));lib=lib.replace(re,(m,a,z)=>a+esc(p.h1)+z+'<p>'+esc(p.description)+'</p>');lib=lib.replace(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g,(m,raw)=>{const d=JSON.parse(raw);for(const n of d['@graph']||[d])if(n['@type']==='ItemList'){const item=n.itemListElement.find(x=>x.url===url);assert(item);item.name=p.h1;}return '<script type="application/ld+json">'+json(d)+'</script>';});fs.writeFileSync(hub,lib);
}
let sitemap=fs.readFileSync(path.join(root,'sitemap.xml'),'utf8');for(const l of locales){const u=origin+(l==='en'?'':'/'+l)+route;sitemap=sitemap.replace(new RegExp('(<loc>'+u+'</loc><lastmod>)[^<]+(</lastmod>)'),'$12026-10-30$2');}fs.writeFileSync(path.join(root,'sitemap.xml'),sitemap);console.log('Follow-up candidate: four complete articles, optional private decision reviews, original source boundaries and routes preserved.');
